void ScriptSession::bindOrderNatives() {
    auto point=[](jass::Value x,jass::Value y){return WorldPoint{jass::Real::fromBits(x.bits),jass::Real::fromBits(y.bits)};};auto id=[](const jass::Value& v){if(!v.text)return 0u;auto known=orderId(*v.text);return known?known:v.text->size()==4?ObjectData::code(*v.text):0u;};
    bind("IssuePointOrder","boolean",{"unit","string","real","real"},[this,point,id](auto& vm,auto a){clearPlayerOrders(a[0].bits);return vm.boolean(moveUnit(a[0].bits,point(a[2],a[3]),id(a[1])));});
    bind("IssuePointOrderById","boolean",{"unit","integer","real","real"},[this,point](auto& vm,auto a){clearPlayerOrders(a[0].bits);return vm.boolean(moveUnit(a[0].bits,point(a[2],a[3]),a[1].bits));});
    bind("IssuePointOrderLoc","boolean",{"unit","string","location"},[this,id](auto& vm,auto a){clearPlayerOrders(a[0].bits);auto p=std::get<WorldPoint>(object(a[2],NativeKind::Location).state);return vm.boolean(moveUnit(a[0].bits,p,id(a[1])));});
    bind("IssuePointOrderByIdLoc","boolean",{"unit","integer","location"},[this](auto& vm,auto a){clearPlayerOrders(a[0].bits);auto p=std::get<WorldPoint>(object(a[2],NativeKind::Location).state);return vm.boolean(moveUnit(a[0].bits,p,a[1].bits));});
    bind("IssueBuildOrder","boolean",{"unit","string","real","real"},[this,point](auto& vm,auto a){auto type=a[1].text?definitions().unitId(*a[1].text):0;clearPlayerOrders(a[0].bits);return vm.boolean(type && build(a[0].bits,type,point(a[2],a[3])));});
    bind("IssueBuildOrderById","boolean",{"unit","integer","real","real"},[this,point](auto& vm,auto a){clearPlayerOrders(a[0].bits);return vm.boolean(build(a[0].bits,a[1].bits,point(a[2],a[3])));});
    bind("IssueImmediateOrderById","boolean",{"unit","integer"},[this](auto& vm,auto a){if(!a[0].bits)return vm.boolean(false);clearPlayerOrders(a[0].bits);if(castImmediateOrder(a[0].bits,a[1].bits))return vm.boolean(true);if(a[1].bits==852025 || a[1].bits==852026 || a[1].bits==852162 || a[1].bits==852163 || a[1].bits==852203 || a[1].bits==852204)return vm.boolean(repairAutocast(a[0].bits,a[1].bits==852025 || a[1].bits==852162 || a[1].bits==852203));if(a[1].bits==852020)return vm.boolean(returnResources(a[0].bits));if(a[1].bits==851976)return vm.boolean(cancelBuildingUpgrade(a[0].bits) || cancelConstruction(a[0].bits) || cancelProduction(a[0].bits));if(a[1].bits==851972 || a[1].bits==851993)return vm.boolean(stopUnit(a[0].bits,a[1].bits==851993));if(upgradeBuilding(a[0].bits,a[1].bits))return vm.boolean(true);return vm.boolean(definitions().upgrade(a[1].bits)?research(a[0].bits,a[1].bits):train(a[0].bits,a[1].bits));});
    bind("GetIssuedOrderId","integer",{},[this](auto& vm,auto){return vm.integer(contexts_.empty()?0:std::bit_cast<std::int32_t>(contexts_.back().issuedOrder));});
    bind("GetOrderedUnit","unit",{},[this](auto& vm,auto){return vm.handle("unit",contexts_.empty() || !contexts_.back().issuedOrder?0:contexts_.back().triggerUnit);});
    bind("GetOrderPointX","real",{},[this](auto& vm,auto){return vm.real(contexts_.empty()?jass::Real{}:contexts_.back().orderPoint.x);});
    bind("GetOrderPointY","real",{},[this](auto& vm,auto){return vm.real(contexts_.empty()?jass::Real{}:contexts_.back().orderPoint.y);});
    bind("GetOrderPointLoc","location",{},[this](auto&,auto){auto p=contexts_.empty()?WorldPoint{}:contexts_.back().orderPoint;auto handle=create(NativeKind::Location);std::get<WorldPoint>(object(handle,NativeKind::Location).state)=p;return handle;});
}
